"""Generate the numerical report from saved results, without rerunning checks."""
from pathlib import Path
import json
import numpy as np
p=Path(__file__).resolve().parent
r=json.loads((p/'results.json').read_text())
q=[x for x in r['quadrature'] if x['order']==256]
small=[x for x in q if x['t']<=.02]
fits={d:float(np.polynomial.polynomial.polyfit([x['t'] for x in small],[x['ratio'] for x in small],d)[0]) for d in [1,2,3]}
resolution=max(abs(x['ratio']-next(y['ratio'] for y in q if y['t']==x['t'])) for x in r['quadrature'])
lines=['# Численная проверка энергетической асимптотики', '',
'Численная проверка однобитовой энергетической асимптотики. Единицы энергии: Eκ = 1; F = ΔE/Eκ. Вычисления в double precision, NumPy '+r['numpy_version']+'.', '',
'## Методика', '',
'1. Квадратура. Для каждого t решено уравнение нормировки интеграла из приложения A бисекцией по c. Интегрирование Гаусса–Лежандра: 64, 128, 256 узлов. Энергия вычислена устойчивой формулой F = [(v−1)²/v]/4, где v = √(c−2t cos z); улучшение ошибки δ = [cos z (1/v−1)]/2. Эти равенства используют [1/v] = 1. Формулы вычисления не используют проверяемый коэффициент B.', '',
'2. Независимая минимизация F−tδ в реальном классе α = φ/2 + Σ aₙ sin(2nφ). Энергия вычисляется по коэффициентам Фурье, ошибка — интегрированием исходного эффекта, без квадратуры приложения. Использован метод Ньютона с аналитическими градиентом, гессианом и поиском шага. Остановка при норме градиента < 10⁻¹³ либо норме ньютоновского шага < 3×10⁻¹⁶; конечная невязка обязательно проверяется на порог 10⁻¹¹. Поиск шага учитывает округление функционала. Неудача приводит к исключению. Число гармоник: 8, 16, 32, 64. Интегралы разбиты в точках разрыва sign(cos φ); по 256 узлов на четверть, контроль с 384. Начальные коэффициенты нулевые, дополнительно три случайных старта. Коэффициент B и функция h в оптимизатор не передаются.', '',
'Это оптимизация лагранжиана, а не отдельная задача с фиксированным δ: для каждого решения измерены его собственные F и δ. Симметрия профиля ограничена указанным реальным подпространством. Поиск по всем комплексным инструментам и скрытым каналам не проводился.', '',
'3. Спектральный контроль. По численно оптимизированному профилю построены qₜ и комплексные матрицы Галёркина операторов L₀,ₜ и L₁,ₜ на антипериодическом базисе exp(i(l+1/2)φ). Для cutoff = M использовано 2M мод. Проверены низшие уровни обоих операторов при t = 0.02 и M = 8, 16, 32, 64. Профиль и оператор уточнялись одновременно; отдельное увеличение порядка квадратуры выполнено на последнем разрешении.', '',
'## Коэффициент', '', f'Аналитический ориентир: 1/B = {r["target"]:.12f}.', '',
'| t | δ | F/δ², квадратура |', '|---:|---:|---:|']
for x in q:lines.append(f'| {x["t"]:g} | {x["delta"]:.10g} | {x["ratio"]:.10f} |')
lines += ['',f'Максимальное различие F/δ² между порядками квадратуры 64, 128 и 256 на этой сетке t: {resolution:.3g}. Это эмпирическая проверка устойчивости, не строгая граница погрешности.', '',
'Экстраполяция F/δ² к t = 0 полиномами по t на точках 0.02, 0.01, 0.005, 0.002, 0.001 (свободный член не фиксировался):', '', '| Степень | Свободный член | Отклонение от 1/B |', '|---:|---:|---:|']
for d,v in fits.items():lines.append(f'| {d} | {v:.12f} | {v-r["target"]:.3g} |')
lines += ['', 'Квадратичная и кубическая экстраполяции согласуются на уровне около 10⁻⁸; последние цифры кубического результата не являются сертифицированной точностью.', '',
'## Сходимость оптимизации при t = 0.02', '', '| Гармоники | F/δ² | Отклонение от квадратуры |', '|---:|---:|---:|']
ref=next(x['ratio'] for x in q if x['t']==.02)
for x in r['fourier']:
 if x['t']==.02 and x['seed']==0 and x['order']==256:lines.append(f'| {x["modes"]} | {x["ratio"]:.10f} | {x["ratio"]-ref:.3g} |')
lines += ['', 'Три случайных старта на 32 гармониках дали то же значение F/δ² с различиями менее 10⁻¹⁰. Увеличение числа узлов с 256 до 384 при 64 гармониках меняет отношение примерно на 4×10⁻¹³. Ошибка усечения гармоник заметно больше ошибки интегрирования.', '',
'## Спектр при t = 0.02', '', '| M | Нижний уровень L₀ | Второй уровень L₀ |', '|---:|---:|---:|']
for x in r['spectra']:
 if x['order']==256:lines.append(f'| {x["cutoff"]} | {x["L0"][0]:.4g} | {x["L0"][1]:.10f} |')
last=r['spectra'][-1]
lines += ['',f'На последнем контрольном разрешении для L₁: λ₀ = {last["L1"][0]:.4g}, λ₁ = {last["L1"][1]:.10f}. Следующие уровни обоих операторов около 2.00430 и 2.00849. Линейное предсказание второго уровня 2t/π ≈ {2*.02/np.pi:.8f}; отклонение согласуется с поправкой второго порядка, но её порядок по одной точке t не проверялся.', '',
'Нижний уровень стремится к нулю, остальные показанные уровни положительны. Нулевая мода не навязывалась матрице. Эти расчёты не исключают отрицательного направления вне конечного базиса: неотрицательность полного оператора обеспечивается аналитическим доказательством.', '',
'## Вывод и ограничения', '',
'На проверенных разрешениях численная проверка поддерживает коэффициент 2π²/(π²−8), нормировки и локальную спектральную картину. Расхождения, указывающие на ошибку множителя или знака, не обнаружены. Проверка не устанавливает новизну, не строит полную границу, не даёт строгого δ₀ или сертифицированного остатка и не заменяет глобальную нижнюю оценку для комплексных счётных каналов.', '',
'## Воспроизведение', '', 'Требуются Python 3 и NumPy; SciPy не используется.', '', '```sh', 'OPENBLAS_NUM_THREADS=1 python3 check.py', 'python3 validate.py', 'python3 summarize.py', 'python3 export_tex.py', '```', '',
'check.py сохраняет все результаты в results.json; validate.py проверяет производные конечными разностями и повторяемость; summarize.py восстанавливает этот отчёт; export_tex.py генерирует векторный рисунок PGFPlots и таблицу в ../figures/. Команды выше выполняются из каталога numerical-check/. Дополнительные двухбитовые проверки запускаются командами `python3 check_two_digits.py` и `python3 verify_two_digits.py`; они сохраняют two-digits-results.json и two-digits-verification.json.', '']
(p/'README.md').write_text('\n'.join(lines))
print('Report saved:',p/'README.md')
